import { render } from '@testing-library/react';
import React from 'react';
import { ProgressTracker } from '../../../..';

describe('ProgressTrackerHeader', () => {
  it('should be shown a console warn when the ProgressTracker.Header is called outside a ProgressTracker.Root component', () => {
    jest.spyOn(console, 'warn').mockImplementation();
    render(<ProgressTracker.Header />);
    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining(
        'Make sure of ProgressTracker.Header component is subcomponent of ProgressTracker.Root.'
      )
    );
  });
});
